_CRASH_CHILD_SCRIPT = r"""
import json
import os
import pathlib
import sys

sys.path.insert(0, sys.argv[1])
import app

log_path = sys.argv[2]
spec = json.loads(sys.argv[3])
crash = spec.get("crash")

real_fsync = os.fsync
counter = {"n": 0}

if crash and crash["kind"] == "after_record":
    target = crash["n"]

    def fsync_hook(fd):
        real_fsync(fd)
        counter["n"] += 1
        if counter["n"] == target:
            # The record is durable; die before any in-memory adoption,
            # exactly like a kill at this write boundary.
            os._exit(3)

    os.fsync = fsync_hook
elif crash and crash["kind"] == "mid_record":
    target = crash["record"]
    cut = crash["cut"]
    real_open = pathlib.Path.open

    class CrashingWriter:
        def __init__(self, wrapped):
            self._wrapped = wrapped

        def __enter__(self):
            return self

        def __exit__(self, *exc):
            self._wrapped.close()
            return False

        def __getattr__(self, name):
            return getattr(self._wrapped, name)

